      "description": "A framework that uses a critic model to generate reflection tokens for evaluating retrieved passages and task outputs, and trains a generator model to produce such tokens autonomously."
    },
    {
      "name": "criticC",
      "type": "MODEL",
      "description": "A critic model trained to evaluate retrieved passages and task outputs by generating reflection tokens, used to update the training corpus offline."
    },
