      "description": "A reference to a study indicating that manual annotation of reflection tokens is expensive."
    },
    {
      "name": "Liu et al., 2023a",
      "type": "ORGANIZATION",
      "description": "A reference to a work that introduced the concept of 'perceived' utility value independent of retrieved passages."
    },
    {
      "name": "perceived utility value",
      "type": "CONCEPT",
      "description": "A metric used in the training of the critic model that reflects the utility of a passage without depending on the retrieved content."
    },
    {
      "name": "conventional LM objective",
      "type": "TASK",
      "description": "The training objective used to train the final generator model M to generate reflection tokens without relying on the critic at inference time."
